impl Instruction {
    /// Wrap this instruction with an address for formatting.
    pub fn at(self, address: u64) -> InstructionAt {
        InstructionAt {
            inst: self,
            address,
        }
    }
}

/// An instruction with its address, for formatting.
#[derive(Debug, Clone, Copy)]
pub struct InstructionAt {
    /// The instruction.
    pub inst: Instruction,
    /// The address of the instruction.
    pub address: u64,
}
